.message-bubble {
    padding: 8px 12px;
    border-radius: 4px;
    position: relative;
}

.message-bubble:hover {
    background: #2e3035;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 4px;
}

.message-author {
    font-weight: 600;
    font-size: 0.9rem;
    color: #f2f3f5;
}

.message-time {
    font-size: 0.75rem;
    color: #949ba4;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    color: #dbdee1;
}

.message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

.reaction-badge {
